package com.example.starter.evidence;

/**
 * 跨案移交状态。
 * COMPLETED 已完成：一次提交在同一事务内完成移出/移入/快照，证物即刻归属目标案件；
 * REVOKED 已撤销（终态）：仅追加反向链，原移交与快照不删除、不可再变。
 */
public enum CaseTransferStatus {
    COMPLETED,
    REVOKED
}

package com.example.starter.evidence;

/**
 * 双案封存快照方。
 * SOURCE 来源案件移出快照；TARGET 目标案件移入快照。同一 transferId 每件证物固定各一行。
 */
public enum SnapshotSide {
    SOURCE,
    TARGET
}

package com.example.starter.evidence;

/**
 * 跨案保管链事件类型。时间均为 UTC，微秒精度；记录只追加、不可变。
 * CASE_TRANSFER_OUT 来源案件移出链；CASE_TRANSFER_IN 目标案件移入链；
 * CASE_TRANSFER_REVOKE_OUT 撤销时目标案件移出链；CASE_TRANSFER_REVOKE_IN 撤销时来源案件移回链。
 */
public enum ChainEventType {
    CASE_TRANSFER_OUT,
    CASE_TRANSFER_IN,
    CASE_TRANSFER_REVOKE_OUT,
    CASE_TRANSFER_REVOKE_IN
}

